package com.qrid.servlet;
import com.qrid.dao.*;import com.qrid.model.*;import com.qrid.util.QrUtil;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.util.Base64;
@WebServlet(urlPatterns={"/security/scanner","/verify"}) public class ScannerServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if("/security/scanner".equals(r.getServletPath())){r.getRequestDispatcher("/WEB-INF/views/security/scanner.jsp").forward(r,s);return;}verify(r,s,r.getParameter("token"));}
 protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{String data=r.getReader().readLine();if(data==null||!data.startsWith("data:image/"))throw new IllegalArgumentException("No camera image received");int comma=data.indexOf(',');byte[] image=Base64.getDecoder().decode(data.substring(comma+1));if(image.length>4_000_000)throw new IllegalArgumentException("Image too large");String decoded=QrUtil.decode(image);String token=decoded.contains("token=")?decoded.substring(decoded.indexOf("token=")+6).split("[&#]")[0]:decoded;verify(r,s,token);}catch(Exception e){r.setAttribute("scanError","No QR code was detected. Hold the card steady and try again.");r.getRequestDispatcher("/WEB-INF/views/security/verify-result.jsp").forward(r,s);}}
 private void verify(HttpServletRequest r,HttpServletResponse s,String token)throws ServletException,IOException{User u=(User)r.getSession().getAttribute("user");if(u==null){s.sendRedirect(r.getContextPath()+"/login");return;}try{Identity x=token==null?null:new IdentityDao().findByToken(token);String result;if(x==null)result="NOT_FOUND";else if(!"ACTIVE".equals(x.getStatus()))result=x.getStatus();else if(x.getValidUntil()!=null&&x.getValidUntil().before(new java.sql.Date(System.currentTimeMillis())))result="EXPIRED";else result="VALID";new ScanDao().record(x==null?null:x.getId(),u.getId(),r.getParameter("gate")!=null?r.getParameter("gate"):"Main Gate",result,r.getRemoteAddr());r.setAttribute("identity",x);r.setAttribute("result",result);r.getRequestDispatcher("/WEB-INF/views/security/verify-result.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}
}
